namespace sv_77bce2f2d0df4e499e9188e851f349f7.Components;

public enum ScreenSize
{
    Mobile,
    Tablet,
    Desktop
}

@implements IAsyncDisposable
@inject IJSRuntime JS

<CascadingValue Value="CurrentScreenSize">
    @ChildContent
</CascadingValue>

@code {
    [Parameter]
    public RenderFragment? ChildContent { get; set; }

    public ScreenSize CurrentScreenSize { get; private set; } = ScreenSize.Desktop;

    private IJSObjectReference? _module;
    private DotNetObjectReference<ScreenSizeProvider>? _dotNetRef;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _dotNetRef = DotNetObjectReference.Create(this);
            _module = await JS.InvokeAsync<IJSObjectReference>(
                "import", "./_content/sv-77bce2f2d0df4e499e9188e851f349f7/Components/ScreenSizeProvider.razor.js");
            var width = await _module.InvokeAsync<int>("initialize", _dotNetRef);
            UpdateCategory(width);
            StateHasChanged();
        }
    }

    [JSInvokable]
    public void OnResize(int width)
    {
        var newSize = Categorize(width);
        if (newSize != CurrentScreenSize)
        {
            CurrentScreenSize = newSize;
            StateHasChanged();
        }
    }

    private void UpdateCategory(int width)
    {
        CurrentScreenSize = Categorize(width);
    }

    private static ScreenSize Categorize(int width) => width switch
    {
        < 768 => ScreenSize.Mobile,
        < 1024 => ScreenSize.Tablet,
        _ => ScreenSize.Desktop
    };

